-- 1) 수량 검증: 56 / 31 / 25 기대
SELECT COUNT(*) AS total_area_count FROM lifestyle_area;
SELECT COUNT(*) AS gyeonggi_area_count FROM lifestyle_area WHERE HEX(sido) = 'EAB2BDEAB8B0EB8F84';
SELECT COUNT(*) AS seoul_area_count FROM lifestyle_area WHERE HEX(sido) = 'EC849CEC9AB8ED8AB9EBB384EC8B9C';

-- 2) 저장 바이트 검증: terminal 표시가 깨져도 HEX가 맞으면 DB 저장은 정상
SELECT area_code, HEX(sido) AS sido_hex, HEX(sigungu) AS sigungu_hex
FROM lifestyle_area
WHERE area_code IN ('GG-SUWON','GG-SEONGNAM','GG-GOYANG','GG-GAPYEONG','SEO-GANGNAM')
ORDER BY area_code;

-- 3) 사람이 읽는 표시 확인
SELECT area_code, sido, sigungu
FROM lifestyle_area
ORDER BY area_code
LIMIT 20;